Q: How to display FlutterMap inside custom shape image without black background? A: <p>You have to convert that to a <code>Path</code> in flutter and then by using <code>ClipPath</code> widget you can clip the Map or any other widget in any shape you want. like this</p>
<pre class="lang-dart prettyprint-override"><code>return Scaffold(
    backgroundColor: Colors.white,
    body: SizedBox(
      height: double.infinity,
      width: double.infinity,
      child: ClipPath(
        clipper: CustomClipPath(),
        child: FlutterMap(children: []), // your map widget
      ),
    ),
  );
</code></pre>
<p>Here is the <code>CustomClipPath</code> class which CustomClipper and return a star shape(you have to return you desired shape from the getPath function)</p>
<pre class="lang-dart prettyprint-override"><code>class CustomClipPath extends CustomClipper&lt;Path&gt; {
  @override
  Path getClip(Size size) {
    final int corners = 4;
    var path = Path();
    var halfWidth = size.width / 2;
    var halfHeight = size.height / 2;
    var radius = halfWidth;
    var innerRadius = halfWidth / 2.5;

    var step = (pi * 2) / corners;
    var halfStep = step / 2;
    var startAngle = -pi / 2;

    path.moveTo(
      halfWidth + cos(startAngle) * radius,
      halfHeight + sin(startAngle) * radius,
    );

    for (int i = 1; i &lt;= corners; i++) {
      var x = halfWidth + cos(startAngle + (step * i) - halfStep) * innerRadius;
      var y =
          halfHeight + sin(startAngle + (step * i) - halfStep) * innerRadius;
      path.lineTo(x, y);

      x = halfWidth + cos(startAngle + (step * i)) * radius;
      y = halfHeight + sin(startAngle + (step * i)) * radius;
      path.lineTo(x, y);
    }

    path.close();
    return path;
  }

  @override
  bool shouldReclip(CustomClipper&lt;Path&gt; oldClipper) =&gt; true;
}
</code></pre>
